pre-actions.script:
// read before anything renders: docs that are off or a page that is not there is the framework's Not Found, and the
// ref picker's choice is answered by a redirect
smithyDocs=ec.resource.script('component://mr-pass/screen/Smithy/SmithySite.js').docs(smithyRepository,String(refPath || ''),passBases,siteInfo,String(publicPath || ''))
if(smithyDocs.redirect){ec.resource.script('component://mr-pass/screen/Smithy/Smithy.js').redirectBefore(sri,smithyDocs.redirect);return}
